// internal/distributed/proxy/httpserver/utils.go lines 543-552
case schemapb.DataType_FloatVector:
    if dataString == "" {
        return reallyDataArray, validDataMap, merr.WrapErrParameterInvalid(schemapb.DataType_name[int32(fieldType)], "", "missing vector field: "+fieldName)
    }
    var vectorArray []float32
    err := json.Unmarshal([]byte(dataString), &vectorArray)
    if err != nil {
        return reallyDataArray, validDataMap, merr.WrapErrParameterInvalid(schemapb.DataType_name[int32(fieldType)], dataString, err.Error())
    }
    reallyData[fieldName] = vectorArray

// Key issue: dataString comes from fieldValue.String() (line 530)
// When input is {"vector": "[0.1,0.2,0.3,0.4]"}, fieldValue.String() returns "[0.1,0.2,0.3,0.4]" (string)
// Then json.Unmarshal([]byte("[0.1,0.2,0.3,0.4]"), &vectorArray) performs SECOND-LEVEL parsing
// This creates type coercion: string → array, which should be rejected at first level
